CREATE COLUMN TABLE "TEST_AP"."@OTHERSETINGS" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_Value" DECIMAL(21,6) CS_FIXED, "U_Value2" NVARCHAR(100), "U_Descriptions" NVARCHAR(200), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KOTHERSETINGS_NAME" ON "TEST_AP"."@OTHERSETINGS" ( "Name" ASC )